// Calculate Previous Month Range
const config = $input.first().json;
const now = new Date();

// Calculate year and month for previous month
let prevYear = now.getFullYear();
let prevMonth = now.getMonth(); // 0 is January, 9 is October

if (prevMonth === 0) {
  prevMonth = 12;
  prevYear -= 1;
} // 1-indexed for string formatting

const monthStr = `${prevYear}-${String(prevMonth).padStart(2, '0')}`;

// UTC bounds for 30 days
const startDate = new Date(Date.UTC(prevYear, prevMonth - 1, 1, 0, 0, 0));
const nextMonthDate = new Date(Date.UTC(prevYear, prevMonth, 1, 0, 0, 0));

return [{
  json: {
    ...config,
    reportMonth: monthStr,
    startTimeUtc: startDate.toISOString(),
    endTimeUtc: nextMonthDate.toISOString(),
    generatedDate: now.toISOString().split('T')[0]
  }
}];

// Aggregate calls for group members and build HTML + CSV binary
const config = $('Calculate Previous Month').first().json;
const month = config.reportMonth;
const membersData = $('Get Group Members').first().json.items || [];
const cdrData = $input.first().json.items || $input.first().json || [];

const members = membersData.map(m => ({
  personId: m.personId || m.id,
  name: m.displayName || m.name || m.email || 'Unknown',
  email: m.email || ''
})).filter(m => m.personId);

const stats = {};
const emailMap = {};
for (const m of members) {
  stats[m.personId] = {
    name: m.name,
    email: m.email,
    inbound: 0,
    outbound: 0,
    total: 0,
    talkSec: 0,
    talkMin: 0
  };
  if (m.email) {
    emailMap[m.email.toLowerCase()] = stats[m.personId];
  }
}

for (const rec of cdrData) {
  const answered = Boolean(rec.answered || rec.isAnswered || rec.answer_indicator);
  const duration = parseInt(rec.duration || rec.durationSeconds || 0, 10);
  if (!answered || duration <= 0) continue;

  const orig = rec.originatingUserId || rec.originatingUserEmail;
  const term = rec.terminatingUserId || rec.terminatingUserEmail;

  if (orig) {
    const target = stats[orig] || emailMap[String(orig).toLowerCase()];
    if (target) {
      target.outbound += 1;
      target.talkSec += duration;
    }
  }

  if (term) {
    const target = stats[term] || emailMap[String(term).toLowerCase()];
    if (target) {
      target.inbound += 1;
      target.talkSec += duration;
    }
  }
}

const rows = Object.values(stats).map(s => {
  s.total = s.inbound + s.outbound;
  s.talkMin = Math.round((s.talkSec / 60) * 10) / 10;
  return s;
});
rows.sort((a, b) => b.total - a.total || a.name.localeCompare(b.name));

const totals = rows.reduce((acc, r) => {
  acc.inbound += r.inbound;
  acc.outbound += r.outbound;
  acc.total += r.total;
  acc.talkMin = Math.round((acc.talkMin + r.talkMin) * 10) / 10;
  return acc;
}, { inbound: 0, outbound: 0, total: 0, talkMin: 0, users: rows.length });

// Generate CSV
const csvLines = [
  `"Webex Call Report","${month}"`,
  `"Name","Email","Inbound Calls","Outbound Calls","Total Calls","Talk Time (min)"`
];
for (const r of rows) {
  csvLines.push(`"${r.name}","${r.email}",${r.inbound},${r.outbound},${r.total},${r.talkMin}`);
}
csvLines.push(`"TOTAL","",${totals.inbound},${totals.outbound},${totals.total},${totals.talkMin}`);
const csvContent = csvLines.join("\r\n");

return [{
  json: {
    month,
    rows,
    totals,
    emailRecipients: config.emailRecipients
  },
  binary: {
    data: {
      data: Buffer.from(csvContent, 'utf-8').toString('base64'),
      mimeType: 'text/csv',
      fileName: `webex_call_report_${month}.csv`,
      fileExtension: 'csv'
    }
  }
}];

// Prepare HTML Email Body and Attach Pre-built CSV
const config = $('Calculate Previous Month').first().json;
const stats = $('Get Monthly Aggregated Stats').first().json;
const csvBinary = $('Download Pre-built CSV').first().binary.data;

const month = stats.month || config.reportMonth;
const rows = stats.rows || [];

const totals = rows.reduce((acc, r) => {
  acc.inbound += (r.inbound || 0);
  acc.outbound += (r.outbound || 0);
  acc.total += (r.total || 0);
  acc.talkMin = Math.round((acc.talkMin + (r.talk_min || 0)) * 10) / 10;
  return acc;
}, { inbound: 0, outbound: 0, total: 0, talkMin: 0, users: rows.length });

return [{
  json: {
    month,
    rows,
    totals,
    emailRecipients: config.emailRecipients
  },
  binary: {
    data: csvBinary
  }
}];

// Build Executive HTML Email Body
const item = $input.first();
const month = item.json.month;
const rows = item.json.rows || [];
const totals = item.json.totals;
const recipients = item.json.emailRecipients;

const htmlBody = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; background-color: #f8fafc; color: #0f172a; margin: 0; padding: 24px; }
    .container { max-width: 800px; margin: 0 auto; background: #ffffff; border-radius: 8px; border: 1px solid #e2e8f0; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05); }
    .header { background-color: #000097; color: #ffffff; padding: 24px 32px; border-bottom: 4px solid #c80030; }
    .header h1 { margin: 0 0 6px 0; font-size: 22px; font-weight: 700; }
    .header p { margin: 0; font-size: 14px; opacity: 0.85; }
    .content { padding: 28px 32px; }
    .cards { display: flex; gap: 16px; margin-bottom: 28px; }
    .card { flex: 1; background: #f4f6fb; border: 1px solid #e2e8f0; border-radius: 6px; padding: 14px; text-align: center; }
    .card-val { font-size: 22px; font-weight: bold; margin-bottom: 4px; }
    .card-lbl { font-size: 11px; font-weight: 600; text-transform: uppercase; color: #64748b; letter-spacing: 0.5px; }
    .navy-text { color: #000097; }
    .red-text { color: #c80030; }
    .dark-text { color: #0f172a; }
    table { width: 100%; border-collapse: collapse; margin-top: 12px; font-size: 13px; }
    th { background: #000097; color: #ffffff; text-align: left; padding: 10px 12px; font-weight: 600; font-size: 12px; }
    th.num, td.num { text-align: right; }
    td { padding: 9px 12px; border-bottom: 1px solid #e2e8f0; }
    tr:nth-child(even) td { background-color: #f8fafc; }
    tr.total-row td { background-color: #f1f5f9; font-weight: bold; border-top: 2px solid #000097; }
    .footer { padding: 16px 32px; background: #f8fafc; border-top: 1px solid #e2e8f0; font-size: 12px; color: #64748b; text-align: center; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>Webex Monthly Call Report</h1>
      <p>National Finance Company &bull; Performance summary for <strong>${month}</strong> (Handled calls only)</p>
    </div>
    <div class="content">
      <div class="cards">
        <div class="card">
          <div class="card-val navy-text">${totals.inbound}</div>
          <div class="card-lbl">Inbound Calls</div>
        </div>
        <div class="card">
          <div class="card-val red-text">${totals.outbound}</div>
          <div class="card-lbl">Outbound Calls</div>
        </div>
        <div class="card">
          <div class="card-val dark-text">${totals.total}</div>
          <div class="card-lbl">Total Handled</div>
        </div>
        <div class="card">
          <div class="card-val dark-text">${totals.users}</div>
          <div class="card-lbl">Active Users</div>
        </div>
      </div>
      <h3 style="margin-bottom: 8px; color: #0f172a;">Call Handling Breakdown by User</h3>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Email</th>
            <th class="num">Inbound</th>
            <th class="num">Outbound</th>
            <th class="num">Total</th>
            <th class="num">Talk Time (min)</th>
          </tr>
        </thead>
        <tbody>
          ${rows.map(r => `
          <tr>
            <td>${r.name || 'Unknown'}</td>
            <td>${r.email || '—'}</td>
            <td class="num">${r.inbound}</td>
            <td class="num">${r.outbound}</td>
            <td class="num"><strong>${r.total}</strong></td>
            <td class="num">${r.talkMin !== undefined ? r.talkMin : r.talk_min}</td>
          </tr>`).join('')}
          <tr class="total-row">
            <td>TOTAL</td>
            <td>—</td>
            <td class="num">${totals.inbound}</td>
            <td class="num">${totals.outbound}</td>
            <td class="num">${totals.total}</td>
            <td class="num">${totals.talkMin}</td>
          </tr>
        </tbody>
      </table>
    </div>
    <div class="footer">
      National Finance Company SAOG &bull; Confidential Monthly Telephony Report &bull; Full CSV detail attached
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    month,
    recipients,
    subject: `Webex Calling Monthly Report — ${month}`,
    htmlBody
  },
  binary: item.binary
}];
